<script setup>defineProps({ clientes: { type: Array, required: true } }); defineEmits(['editar', 'eliminar'])</script>
<template><div class="overflow-x-auto rounded-xl border border-slate-200 bg-white"><table class="min-w-full text-left text-sm"><thead class="bg-slate-100 text-slate-600"><tr><th class="px-5 py-4">Nombre</th><th class="px-5 py-4">Correo electrónico</th><th class="px-5 py-4">Teléfono</th><th class="px-5 py-4 text-right">Acciones</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="cliente in clientes" :key="cliente.id" class="hover:bg-slate-50"><td class="px-5 py-4 font-medium">{{ cliente.nombre }}</td><td class="px-5 py-4">{{ cliente.email }}</td><td class="px-5 py-4">{{ cliente.telefono || '—' }}</td><td class="px-5 py-4"><div class="flex justify-end gap-2"><button type="button" class="rounded-md bg-blue-50 px-3 py-2 font-medium text-blue-700 hover:bg-blue-100" @click="$emit('editar', cliente)">Editar</button><button type="button" class="rounded-md bg-red-50 px-3 py-2 font-medium text-red-700 hover:bg-red-100" @click="$emit('eliminar', cliente)">Eliminar</button></div></td></tr><tr v-if="clientes.length === 0"><td colspan="4" class="px-5 py-12 text-center text-slate-500">No hay clientes para mostrar.</td></tr></tbody></table></div></template>
